Here is an example implementation of a stack data structure in Python:

```python
class Stack(object):
    def __init__(self):
        self.items = []

    # check if stack is empty
    def is_empty(self):
        return len(self.items) == 0

    # add an element to the stack
    def push(self, item):
        self.items.append(item)

    # remove the top-most element from the stack and return it
    def pop(self):
        if not self.is_empty():
            return self.items.pop()
        else:
            return "Stack is empty"

    # check the top-most element of the stack without removing it
    def peek(self):
        if not self.is_empty():
            return self.items[-1]
        else:
            return "Stack is empty"

    #return the size of the stack
    def size(self):
        return len(self.items)


#define a stack
