def findErrorNums(nums):
    n = len(nums)
    seen = set()
    duplicated = missing = None

    for num in nums:
        if num in seen:
            duplicated = num
        else:
            seen.add(num)

    for i in range(1, n+1):
        if i not in seen:
            missing = i

    return [duplicated, missing]
```

